import{_ as s,C as a,o as n,c as i,a2 as e,E as r}from"./chunks/framework.9yf7n3zg.js";const d="/guide/media/writer-board-overview.webp",h="/guide/media/writer-board-column-card.webp",l="/guide/media/writer-board-lines.webp",c="/guide/media/writer-board-column-list.webp",b=JSON.parse('{"title":"The Writer Board","description":"","frontmatter":{},"headers":[],"relativePath":"guide/writer-board.md","filePath":"guide/writer-board.md","lastUpdated":1791657833000}'),g={name:"guide/writer-board.md"};function p(m,t,u,w,f,y){const o=a("Clip");return n(),i("div",null,[t[0]||(t[0]=e('<h1 id="the-writer-board" tabindex="-1">The Writer Board <a class="header-anchor" href="#the-writer-board" aria-label="Permalink to &quot;The Writer Board&quot;">​</a></h1><p>The Writer Board sits above every story. It holds what you are made of as a writer: the themes you keep arguing about, the people you keep writing, the premises waiting for a home, the quotes and research that outlive one book. It is a panel of lists you pan and zoom, with your stories and your ideas first and the lists of a framework below. This page covers every part of it: the lists, the cards, dragging, links and lines, the side column, and changing the lists to your own.</p><p>Nothing on the board is prose. A card the board makes is a small markdown note Leathercase owns; a note of yours that carries a board tag is shown and never written. Nothing on the board is sent to a model.</p><p><img src="'+d+'" alt="The Writer Board on the sample home: the state line, the Stories and ideas band with the four stories and A lamp that lies, and the top of the Wish list with Genres, Plots, Themes and Archetypes" width="1130" height="852" loading="lazy"></p><h2 id="open-the-board" tabindex="-1">Open the board <a class="header-anchor" href="#open-the-board" aria-label="Permalink to &quot;Open the board&quot;">​</a></h2><p>Click <strong>Writer</strong> under <strong>Home</strong> in the sidebar, or press <code>Ctrl+3</code> (Cmd+3 on macOS). The board belongs to the writing home, not to one story, so it is there whichever story you were in.</p><p>The line at the top of the board counts what is on it: <strong>6 cards · 4 stories · 1 idea · Truby</strong>, then any filter in force, then the zoom, such as <strong>80%</strong>. The board&#39;s menu, <strong>⋯</strong> at the top right (<strong>Writer menu</strong>), holds the zoom, the lines and the filters.</p><h2 id="the-panel" tabindex="-1">The panel <a class="header-anchor" href="#the-panel" aria-label="Permalink to &quot;The panel&quot;">​</a></h2><p>The board is a panel larger than the window. The lists stay where the framework puts them; you move the view:</p><ul><li><strong>Drag the background</strong> to pan.</li><li><strong>Scroll the wheel</strong> to zoom in and out around the pointer, or use <strong>Zoom in</strong> and <strong>Zoom out</strong> in the menu, or <code>+</code> and <code>-</code>.</li><li><strong>Fit</strong> in the menu, or <code>f</code>, shows the whole board.</li></ul><p>The first time you open the board, it opens at the width of its widest band, top first, so the lists can be read. After that it opens where you left it; the view is kept in the home&#39;s <code>suite/Writer.json</code>.</p>',11)),r(o,{name:"writer-board-pan",caption:"Panning the board by dragging its background, zooming with the wheel, then Fit from the menu"}),t[1]||(t[1]=e(`<h2 id="the-bands-and-lists" tabindex="-1">The bands and lists <a class="header-anchor" href="#the-bands-and-lists" aria-label="Permalink to &quot;The bands and lists&quot;">​</a></h2><p>The board reads top to bottom in bands, each band a row of lists:</p><ul><li><strong>Stories and ideas</strong>, the first band, holds two fixed lists: <strong>Stories</strong> and <strong>Ideas</strong>.</li><li><strong>The framework&#39;s bands</strong> follow. The default framework is Truby&#39;s, with the bands <strong>Wish list</strong>, <strong>Premises</strong>, <strong>Inspirations</strong>, <strong>References</strong> and <strong>Voices</strong>.</li><li><strong>Unsorted</strong> comes last, and only when it holds something.</li></ul><p>Each list has a head with its colour, its name and how many cards it holds, then the tag a note needs to land in it, such as <code>#writer/theme</code>. An empty list shows its hint, which teaches what to collect, and <strong>make a card here, or tag a note #writer/theme</strong>.</p><h3 id="stories" tabindex="-1">Stories <a class="header-anchor" href="#stories" aria-label="Permalink to &quot;Stories&quot;">​</a></h3><p><strong>Stories</strong> holds one card per story declared in the home. It is not a list you add to: declare a story and its card appears. With no story yet, it says <strong>The stories declared in this library, each a card that opens the desk.</strong></p><p>A story card shows:</p><ul><li>The story&#39;s name, and its stage with a coloured dot: <strong>idea</strong>, <strong>in development</strong>, <strong>drafting</strong>, <strong>revising</strong>, <strong>finished</strong> or <strong>shelved</strong>.</li><li>Its premise, or <strong>No premise yet.</strong></li><li>Its voice, the card named in the story&#39;s note as <code>writing-voice</code>, or <strong>voice none yet</strong>.</li><li>Its words, against its target when it has one, such as <strong>18,420 of 60,000 words</strong>.</li><li>How many are <strong>in the cast</strong>, and the day you last worked on it.</li></ul><p>The stage and premise come from <code>writing-stage</code> and <code>writing-premise</code> in the story&#39;s note, and the voice from <code>writing-voice</code> (see <a href="/guide/guide/scaffold-a-story#step-2-write-the-story-s-note">Scaffold a story folder</a> and <a href="/guide/reference/front-matter#the-writer-board-s-story-card">Front matter</a>). A fourth key, <code>writing-idea</code>, names the premise card the story grew from; a premise card claimed that way, or one whose own <code>writer-story</code> names the story, counts as having found its home. The keys are read every time the board is drawn and never copied into the story&#39;s settings. With no stage written, Leathercase infers one: <strong>finished</strong> when the story holds its target, <strong>drafting</strong> when it has prose, <strong>in development</strong> before that.</p><p>Click a story card to select it; double-click it to open the story.</p><h3 id="ideas" tabindex="-1">Ideas <a class="header-anchor" href="#ideas" aria-label="Permalink to &quot;Ideas&quot;">​</a></h3><p><strong>Ideas</strong> is the list every board has, whatever the framework: story ideas waiting for a home, a what-if, a title, a scene that arrived first. A card with nowhere else to go lands here: plain text made from the find field, and every line captured from another app (see <a href="/guide/guide/find#capture-a-line-from-any-app">Capture a line from any app</a>). Its cards are of the kind idea.</p><h3 id="the-framework-s-lists" tabindex="-1">The framework&#39;s lists <a class="header-anchor" href="#the-framework-s-lists" aria-label="Permalink to &quot;The framework&#39;s lists&quot;">​</a></h3><p>Truby&#39;s framework asks what you care about rather than what happens next. Its lists, with the hints they show when empty:</p><table tabindex="0"><thead><tr><th>Band</th><th>List</th><th>Hint</th><th>Kind of card made in it</th></tr></thead><tbody><tr><td>Wish list</td><td><strong>Genres</strong></td><td>The genres and blends you would love to write in.</td><td>theme</td></tr><tr><td></td><td><strong>Plots</strong></td><td>Plot shapes that keep pulling you: the quest, the confession, the return.</td><td>event</td></tr><tr><td></td><td><strong>Themes</strong></td><td>What you argue about, story after story. One sentence each.</td><td>theme</td></tr><tr><td></td><td><strong>Archetypes</strong></td><td>The people you keep writing: the lone hunter, the mentor at peace.</td><td>character</td></tr><tr><td></td><td><strong>Worlds</strong></td><td>Places and milieus you return to.</td><td>place</td></tr><tr><td></td><td><strong>Dialogues</strong></td><td>Fragments of speech that arrived before any scene.</td><td>character</td></tr><tr><td>Premises</td><td><strong>Premises</strong></td><td>One-line story questions. Promote one when it has a home.</td><td>premise</td></tr><tr><td>Inspirations</td><td><strong>Poems</strong></td><td>Poems that move you.</td><td>reference</td></tr><tr><td></td><td><strong>Notes</strong></td><td>Personal notes: a creed, a thing someone said.</td><td>reference</td></tr><tr><td></td><td><strong>Music</strong></td><td>Songs and their lines.</td><td>reference</td></tr><tr><td></td><td><strong>Videos</strong></td><td>Films, talks, moments on a screen.</td><td>reference</td></tr><tr><td></td><td><strong>Sentiments</strong></td><td>Feelings and concepts you circle: pride, eudaimonia, a motto.</td><td>theme</td></tr><tr><td></td><td><strong>Quotes</strong></td><td>Lines from books, with the page.</td><td>reference</td></tr><tr><td>References</td><td><strong>Craft</strong></td><td>Analyses of other writers&#39; work: what teaches you.</td><td>reference</td></tr><tr><td></td><td><strong>Research</strong></td><td>Research that outlives one story.</td><td>reference</td></tr><tr><td></td><td><strong>Reading</strong></td><td>The reading list. Put reading: to-read, reading or read on the note.</td><td>reference</td></tr><tr><td>Voices</td><td><strong>Voices</strong></td><td>Narrators you have built and might adopt again.</td><td>character</td></tr></tbody></table><p>Leathercase also ships a smaller framework, Generic (<strong>Themes</strong>, <strong>Characters</strong>, <strong>Worlds</strong>, <strong>Ideas</strong>, <strong>Inspirations</strong>, <strong>References</strong>, <strong>Voices</strong>). The app offers no switch between the two today; you make Truby&#39;s lists your own instead (see <a href="#change-the-lists">Change the lists</a>).</p><h3 id="unsorted" tabindex="-1">Unsorted <a class="header-anchor" href="#unsorted" aria-label="Permalink to &quot;Unsorted&quot;">​</a></h3><p>A note tagged under <code>writer/</code> whose tag names no list, such as <code>#writer/wildcard</code>, sits in <strong>Unsorted</strong>, as do the cards of a list you removed. Nothing is lost: give the note a tag of a list, or add a list with that name, and it moves.</p><h2 id="cards-are-notes" tabindex="-1">Cards are notes <a class="header-anchor" href="#cards-are-notes" aria-label="Permalink to &quot;Cards are notes&quot;">​</a></h2><p>A card on the board is one of two things, and the board treats them differently.</p><table tabindex="0"><thead><tr><th></th><th>A card the board made</th><th>A note of yours</th></tr></thead><tbody><tr><td>Where it lives</td><td>The home&#39;s <code>Writer/</code> folder</td><td>Anywhere in the home</td></tr><tr><td>How it joins the board</td><td>Made in a list, from the find field or by capture</td><td>Carries a tag under <code>writer/</code>, in its front matter (<code>tags: [writer/theme]</code>) or in its text (<code>#writer/theme</code>)</td></tr><tr><td>What the board may do</td><td>Rewrite its text, kind, tags and references; retag it when you move it</td><td>Read it, show its first paragraph, place it on the board. Never write it</td></tr><tr><td>How it looks</td><td>A plain card</td><td>A card marked <strong>your note</strong></td></tr></tbody></table><p>A card the board made is author data: a markdown note you can open, edit or move in any program. <code>Writer/What we owe.md</code> reads:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">writer/theme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sea</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">theme</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">created</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2026-10-06</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The drowned.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## References</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [[The keeper who stays]]</span></span></code></pre></div><p>The first tag says which list it sits in; the others are its own tags. <code>kind:</code> is what the card is. The body is its text, and the cards it references are links under <strong>References</strong>. A note in the <code>Writer/</code> folder that lacks the list tag or the <code>created:</code> date is treated as yours, and only read.</p><p>You can choose another folder for the cards: see <a href="#where-the-cards-go">Where the cards go</a>.</p><h2 id="make-a-card" tabindex="-1">Make a card <a class="header-anchor" href="#make-a-card" aria-label="Permalink to &quot;Make a card&quot;">​</a></h2><p>Click <strong>+ a card</strong> at the foot of any list except Stories and Unsorted. A field opens with the placeholder <strong># A title</strong> and <strong>What the card says, with [[links]] to other cards.</strong></p><ul><li>The first line is the card&#39;s title, written as a heading or not.</li><li><code>Enter</code> on a one-line draft makes the card. <code>Shift+Enter</code> starts the text on the next line; once the draft has more than one line, <code>Ctrl+Enter</code> makes the card.</li><li>The button reads <strong>Add</strong> and then <strong>Add &quot;What we owe&quot;</strong> as you type. <strong>Cancel</strong> or <code>Esc</code> lets the draft go.</li><li>A <code>#tag</code> typed in the title or the text leaves it and becomes one of the card&#39;s tags, shown as a chip: <code>Lamp #mystery</code> makes the card Lamp, tagged mystery.</li><li><code>[[Title]]</code> in the text links to another card and draws a line to it.</li></ul><p>The card takes the kind of its list (see the table above) and lands at the top of the list.</p><p>You can also make a card without leaving the keyboard: press <code>n</code> to open the field in the selected card&#39;s list, or in Ideas, or press <code>Ctrl+O</code> and type <code>theme: What we owe</code> in the find field. See <a href="/guide/guide/find#make-something-with-a-word-and-a-colon">Find, open and make</a>.</p>`,30)),r(o,{name:"writer-board-make-card",caption:"Making a card in Themes: the title, a line of text, Enter, and the card on the board"}),t[2]||(t[2]=e('<h2 id="select-a-card-and-the-side-column" tabindex="-1">Select a card and the side column <a class="header-anchor" href="#select-a-card-and-the-side-column" aria-label="Permalink to &quot;Select a card and the side column&quot;">​</a></h2><p>Click a card to select it; click it again, press <code>Esc</code>, or click <strong>close</strong> in the column to let it go. Double-click a card of the board&#39;s to put the caret in its text; double-click a note of yours to open it in the program you write in.</p><p>The side column (<code>Ctrl+B</code> shows or hides it) shows what is selected under <strong>Selected</strong>:</p><p><img src="'+h+'" alt="The side column with a card of the board&#39;s selected: its text, kind, tags, references and lines" width="375" height="635" loading="lazy"></p><ul><li><strong>The title and the file&#39;s path.</strong></li><li><strong>The text</strong>, for a card of the board&#39;s, in a field you can edit. It is saved when you leave the field, press <code>Ctrl+Enter</code>, or leave the board, never on every key, so one edit is one write. For a note of yours, its first paragraph is shown.</li><li><strong>Kind</strong>: a list of the board&#39;s kinds and <strong>untyped</strong>, for a card of the board&#39;s. For a note of yours, its kind as its <code>kind:</code> line says (<strong>a character, by its kind: line</strong>), or <strong>untyped; kind: in the note&#39;s front matter types it</strong>.</li><li><strong>Tags</strong>: the card&#39;s own tags as chips. On a card of the board&#39;s, <code>×</code> takes a tag off, and the field <strong>a tag, new or known</strong> with <strong>+ a tag</strong> puts one on, offering the tags the board knows. <strong>your note&#39;s tags are read, never written</strong> on a note of yours.</li><li><strong>tagged #writer/theme</strong>, and <strong>placed in</strong> a list when the card was moved on the board alone.</li><li><strong>Which stories use it</strong>: <strong>in no story yet</strong>, <strong>in The Lamp at Ferrol</strong>, or <strong>recurs in</strong> two or more. A story uses a card when a note of the story links to it, <code>[[What we owe]]</code>, or names it in a comment, <code>%% REF: [[What we owe]] %%</code>, which stays out of the manuscript and any export. A card that recurs is the simplest picture of what you keep returning to.</li><li><strong>Open note</strong> for a note of yours, and <strong>Put back by its tag</strong> for a card you placed in another list.</li><li><strong>Move to</strong>, a list of the board&#39;s lists (see below).</li><li><strong>References</strong>, for a card of the board&#39;s: the cards it references, each with <strong>drop</strong>, and <strong>reference a card…</strong> to add one. Adding writes a link under the card&#39;s References heading and draws a line.</li><li><strong>The lines</strong> the card has with other cards, each naming the card at the other end and whether it <strong>links</strong>. Click a name to select that card. With none, it says <strong>no line yet; reference a card above</strong>, or for a note of yours, <strong>no line yet; a [[link]] in the note draws one</strong>.</li></ul><p>A selected story shows its stage, words and cast, its premise (or <strong>No premise yet. Put writing-premise on the project note and it shows here.</strong>), its voice, and <strong>Open at the desk</strong>, which opens the story.</p><h2 id="move-a-card" tabindex="-1">Move a card <a class="header-anchor" href="#move-a-card" aria-label="Permalink to &quot;Move a card&quot;">​</a></h2><p>Drag a card to another list, or up and down within one; it lands where you let go. <code>m</code> puts the caret in <strong>Move to</strong> in the column, which moves the selected card to the foot of the list you pick.</p><p>What moving does depends on whose card it is:</p><ul><li><strong>A card of the board&#39;s</strong> is retagged: dragging What we owe from Themes to Craft rewrites its list tag from <code>writer/theme</code> to <code>writer/craft</code> in its note. Its text and its other tags stay.</li><li><strong>A note of yours</strong> moves on the board alone. The note keeps its tag as written; the board remembers the move in <code>suite/Writer.json</code> and marks the card <strong>placed · tag: theme</strong>. <strong>Put back by its tag</strong> returns it to the list its tag names.</li></ul><p>The order you give cards within a list is kept too. A card tagged for two lists shows in both, with <strong>also</strong> and the other list&#39;s name; dragging moves the copy you took.</p>',11)),r(o,{name:"writer-board-drag",caption:"Dragging a card of the board's to another list retags it; dragging your own note places it and leaves the note as written"}),t[3]||(t[3]=e('<h2 id="links-and-lines" tabindex="-1">Links and lines <a class="header-anchor" href="#links-and-lines" aria-label="Permalink to &quot;Links and lines&quot;">​</a></h2><p>A line on the board joins two cards that link to each other: a <code>[[link]]</code> in either card&#39;s text or references.</p><ul><li><strong>Hover a card</strong> and its lines are drawn, and every card it is not joined to dims.</li><li><strong>Select a card</strong> and the same happens while it stays selected.</li><li><strong>Every line</strong>, in the menu or <code>e</code>, draws every line of the board at once; the top line says <strong>every line</strong>.</li></ul><p>A link in a card&#39;s text is underlined. Click it and the board selects the card with that title and moves it to the middle of the view. A link to a note that is not on the board opens the note in the program you write in.</p><p>Each card shows how many lines it has, <strong>2 lines</strong>, at its foot.</p><p><img src="'+l+'" alt="A card selected: its lines drawn to the cards it references, the rest dimmed" width="811" height="587" loading="lazy"></p><h2 id="filter-by-kind-or-tag" tabindex="-1">Filter by kind or tag <a class="header-anchor" href="#filter-by-kind-or-tag" aria-label="Permalink to &quot;Filter by kind or tag&quot;">​</a></h2><p>The menu&#39;s <strong>Kind</strong> section has <strong>Every kind</strong> and each kind on the board; its <strong>Tag</strong> section has <strong>Every tag</strong> and each tag the cards carry. Pick one and every card without it dims; the top line says <strong>theme shown</strong> or <strong>#sea shown</strong>. A tag counts the tags nested under it, so <code>#sea</code> lights cards tagged <code>#sea/charts</code> too. Pick <strong>Every kind</strong> or <strong>Every tag</strong> to clear it.</p><p>A tag given a colour in the <a href="/guide/guide/tags">Tags</a> view shows in that colour on every card.</p><h2 id="kinds" tabindex="-1">Kinds <a class="header-anchor" href="#kinds" aria-label="Permalink to &quot;Kinds&quot;">​</a></h2><p>A kind says what a card is, whichever list it sits in: a character, a place, an event, a theme, a premise, a reference or an idea. A card made in a list takes the list&#39;s kind, or else the first kind of its band; Ideas makes ideas; Unsorted makes none. You can change a card&#39;s kind in the column at any time; only its <code>kind:</code> line changes.</p><p>Each band offers a set of kinds, listed in the column under <strong>Lists</strong>. To add one, type it in <strong>A kind of your own</strong>, pick the band, and click <strong>+ a kind</strong>. To take one from a band, click the <code>×</code> beside it. Cards of that kind keep it as written, and a list that made cards of it makes them of the band&#39;s first kind instead. A band with no kinds says <strong>none; its cards are untyped</strong>.</p><p>Every kind on the board is also a word in the find field: add <code>motif</code> and <code>motif: The bell</code> makes a card.</p><h2 id="change-the-lists" tabindex="-1">Change the lists <a class="header-anchor" href="#change-the-lists" aria-label="Permalink to &quot;Change the lists&quot;">​</a></h2><p>The column&#39;s <strong>Lists</strong> section names the framework and explains: <strong>Stories and Ideas are fixed. The rest are Truby&#39;s lists in its bands, yours to rename, remove and add to; the first change makes the framework your own copy.</strong> After the first change, the section reads <strong>Truby, yours</strong> and the top line says <strong>Truby, yours</strong>.</p><ul><li><strong>Add a list</strong>: type its name in <strong>A list of your own</strong>, pick the band, or <strong>a new band</strong>, and click <strong>+ a list</strong>. Its tag is made from the name, so Smells takes <code>#writer/smells</code>; a new band takes the list&#39;s name.</li><li><strong>Rename a list</strong>: click the list&#39;s head to select it. The column shows its tag, its card count and its hint, a field with its name and <strong>Rename</strong>. The tag stays the same, so every card stays in it.</li><li><strong>Remove a list</strong>: select it and click <strong>Remove the list</strong>. Its cards go to Unsorted with their tags as written; a list with nothing on it goes quietly. The last list of the board cannot be removed.</li></ul><p>Stories, Ideas and Unsorted cannot be renamed or removed.</p><p><img src="'+c+'" alt="The column with the Themes list selected: its tag, Rename and Remove the list, and the Lists section below" width="366" height="1100" loading="lazy"></p><h2 id="where-the-cards-go" tabindex="-1">Where the cards go <a class="header-anchor" href="#where-the-cards-go" aria-label="Permalink to &quot;Where the cards go&quot;">​</a></h2><p>The column&#39;s last section, <strong>Your cards go in</strong>, shows the folder the board writes its cards to, <code>Writer</code> at the home&#39;s root by default. <strong>Choose…</strong> picks another folder in the home; the cards then go in a <code>Writer</code> folder inside it. <strong>Use the default</strong> returns to the home&#39;s root. Each card you make is a markdown note in that folder, tagged for its list. Your other notes are read and never written.</p><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><p>Press <code>?</code> on the board to see its keys. <code>Esc</code> puts the list away.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Ctrl+O</code></td><td>Find or make, in the find field</td></tr><tr><td><code>←</code> <code>→</code> <code>↑</code> <code>↓</code></td><td>Walk the cards, list by list</td></tr><tr><td><code>Enter</code></td><td>Edit the selected card of the board&#39;s, open your note, or open the selected story</td></tr><tr><td><code>n</code></td><td>A new card in the selected card&#39;s list, the selected list, or Ideas</td></tr><tr><td><code>m</code></td><td>Move the selected card</td></tr><tr><td><code>f</code></td><td>Fit the whole board</td></tr><tr><td><code>e</code></td><td>Every line</td></tr><tr><td><code>+</code> <code>-</code></td><td>Zoom in and out</td></tr><tr><td><code>Esc</code></td><td>Deselect</td></tr></tbody></table><h2 id="what-the-board-writes" tabindex="-1">What the board writes <a class="header-anchor" href="#what-the-board-writes" aria-label="Permalink to &quot;What the board writes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What it holds</th></tr></thead><tbody><tr><td><code>Writer/*.md</code></td><td>The cards the board made, one note each</td></tr><tr><td><code>suite/Writer.json</code></td><td>Your own copy of the framework once you change it, the lists you moved your notes to, the order of cards in each list, and the view</td></tr></tbody></table><p>The cards&#39; folder also holds <code>Templates/</code>, where the <a href="/guide/guide/graph">Graph</a> keeps the templates you change or make. Those notes carry no board tag, so they never show as cards.</p><p>The board never writes to a note of yours. When there is nothing on it, it says so: <strong>Nothing on the board yet. Make a card in any list and it becomes a note in your folder; tag a note of your own and it appears here on the next reading. Your notes are read, never written.</strong></p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/find">Find, open and make</a></li><li><a href="/guide/guide/tags">Tags</a></li><li><a href="/guide/guide/beat-board">Beat board</a></li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li></ul>',29))])}const v=s(g,[["render",p]]);export{b as __pageData,v as default};
